export interface Brand {
  id: string;
  name: string;
  slug: string;
  logo: string;
  banner: string;
  logoFont?: string;
  darkCard?: boolean;
  lightCard?: boolean;
  fullBleedLogo?: boolean;
  /** Optional CSS color used as the background for the "Today's Featured Brand" homepage section. */
  themeColor?: string;
  /** Text tone to pair with `themeColor` on the featured brand section. Defaults to "dark". */
  themeTextTone?: "light" | "dark";
  /** Override the brand-name color on BrandCard when default white/black is unreadable against the logo art. */
  nameColor?: "accent" | "white" | "black";
  /** Add a soft accent glow behind the brand name on BrandCard (used when the logo art mixes black + white). */
  nameGlow?: boolean;
  /** Override aesthetic-tag color on BrandCard when default contrast is poor. */
  tagColor?: "dark" | "light" | "accent";
  useLogoImageHero?: boolean;
  bio: string;
  story: string;
  founded: string;
  founderNote?: string;
  vibes: string[];
  origin: string;
  website: string;
  affiliateUrl: string;
  instagram: string;
  tiktok?: string;
  aesthetics: string[];
  categories: string[];
  priceRange: "budget" | "mid" | "premium" | "luxury";
  followers: number;
  rating: number;
  featured: boolean;
  newDrop: boolean;
  /** ISO date (YYYY-MM-DD) when this brand was added to DRIPWAY. Drives the "NEW" badge (last 14 days). */
  addedAt?: string;
  /** Optional lookbook/campaign image URLs shown as a gallery on the brand profile. */
  lookbook?: string[];
}

export interface Product {
  id: string;
  name: string;
  brandId: string;
  brandName: string;
  image: string;
  images: string[];
  price: number;
  originalPrice?: number;
  /** Native prices scraped directly from the brand's site, keyed by currency. */
  prices?: Partial<Record<"USD" | "EUR" | "GBP" | "CAD" | "AUD" | "JPY" | "NGN", number>>;
  description: string;
  category: string;
  aesthetics: string[];
  sizes: string[];
  sizeStock?: Record<string, boolean>;
  affiliateUrl: string;
  trending: boolean;
  newArrival: boolean;
  /** ISO date (YYYY-MM-DD) when this product was fetched/added. Drives the "NEW" badge (last 14 days). */
  addedAt?: string;
  colors?: { name: string; image: string; affiliateUrl: string }[];
}

export interface BlogPost {
  id: string;
  title: string;
  slug: string;
  excerpt: string;
  coverImage: string;
  category: "spotlight" | "trend" | "guide" | "style";
  author: string;
  date: string;
  readTime: number;
}

